fork();
fork();
printf("hi\n");
/* 1 process -> 2 -> 4 processes: 2^n after n forks,
   so this prints "hi" 4 times */

int x = 5;
pid_t pid = fork();
if (pid == 0) { x = 10; exit(0); }   /* child changes ITS copy */
waitpid(pid, NULL, 0);
printf("%d\n", x);                    /* parent still sees 5 */

